// The classes a SWF links against, as natives and hosts reach their
// objects (Runtime.prop, docs/architecture/runtime.md): builtin's,
// playerglobal's and AIR's declarations, generated by tools/as3-types.ts,
// keyed by qualified name. Also @swf2es/player/as3-types, which the
// declarations `swf2es types` writes for a SWF's own classes extend.
import type { avm2 } from "@swf2es/runtime";
import type { AirClasses, AirStatics } from "./air-types.generated.js";
import type { PlayerglobalClasses, PlayerglobalStatics } from "./playerglobal-types.generated.js";

export type { AirClasses, AirStatics, PlayerglobalClasses, PlayerglobalStatics };

/** Each class's instances' public members, by qualified name: "flash.geom::Rectangle". */
export type As3Classes = avm2.BuiltinClasses & PlayerglobalClasses & AirClasses;

/** Each class object's public members. */
export type As3Statics = avm2.BuiltinStatics & PlayerglobalStatics & AirStatics;

/** An instance of the class named `N`, for Runtime.prop, setProp and callProp: `v as As3<"flash.geom::Point">`. */
export type As3<N extends keyof As3Classes> = avm2.Ref<As3Classes[N]>;

/** The class object of the class named `N`. */
export type As3Class<N extends keyof As3Statics> = avm2.Ref<As3Statics[N]>;
